  {
   "cell_type": "markdown",
   "id": "e17303f0",
   "metadata": {},
   "source": [
    "# How Household Income Relates to Exam Outcomes"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 52,
   "id": "64f6f591",
   "metadata": {},
   "outputs": [
    {
     "data": {
      "image/png": "",
      "text/plain": [
       "<Figure size 1000x600 with 1 Axes>"
      ]
     },
     "metadata": {},
     "output_type": "display_data"
    }
   ],
   "source": [
    "# Family Income - Pass vs Fail\n",
    "income_order = [\n",
    "    'Low',\n",
    "    'Lower-Middle',\n",
    "    'Middle',\n",
    "    'Upper-Middle',\n",
    "    'High'\n",
    "]\n",
    "\n",
    "family_income_count = pd.crosstab(\n",
    "    df['family_income'],\n",
    "    df['pass_status']\n",
    ")[['Fail', 'Pass']]\n",
    "\n",
    "# Apply desired order\n",
    "family_income_count = family_income_count.reindex(income_order)\n",
    "\n",
    "# Plot bars\n",
    "ax = family_income_count.plot(\n",
    "    kind='bar',\n",
    "    figsize=(10, 6),\n",
    "    color=['red', 'green']\n",
    ")\n",
    "\n",
    "plt.title('Pass vs Fail by Family Income')\n",
    "plt.xlabel('Family Income')\n",
    "plt.ylabel('Number of Students')\n",
    "plt.xticks(rotation=0)\n",
    "plt.legend(title='Status')\n",
    "\n",
    "# X positions for the two bars\n",
    "x = range(len(family_income_count))\n",
    "\n",
    "# Add connecting lines between the columns\n",
    "fail_values = family_income_count['Fail'].values\n",
    "pass_values = family_income_count['Pass'].values\n",
    "\n",
    "# Positions of Fail and Pass bars\n",
    "fail_x = [i - 0.125 for i in x]\n",
    "pass_x = [i + 0.125 for i in x]\n",
    "\n",
    "# Trend lines\n",
    "plt.plot(\n",
    "    fail_x,\n",
    "    fail_values,\n",
    "    color='darkred',\n",
    "    marker='o',\n",
    "    linewidth=2\n",
    ")\n",
    "\n",
    "plt.plot(\n",
    "    pass_x,\n",
    "    pass_values,\n",
    "    color='darkgreen',\n",
    "    marker='o',\n",
    "    linewidth=2\n",
    ")\n",
    "\n",
    "# Add Count + Percentage\n",
    "for i, category in enumerate(family_income_count.index):\n",
    "\n",
    "    total = family_income_count.loc[category].sum()\n",
    "\n",
    "    for j, status in enumerate(family_income_count.columns):\n",
    "\n",
    "        count = family_income_count.loc[category, status]\n",
    "        percentage = count / total * 100\n",
    "\n",
    "        bar_x = i + (-0.125 if status == 'Fail' else 0.125)\n",
    "\n",
    "        ax.text(\n",
    "            bar_x,\n",
    "            count,\n",
    "            f'{count:,}\\n({percentage:.1f}%)',\n",
    "            ha='center',\n",
    "            va='bottom',\n",
    "            fontweight='bold'\n",
    "        )\n",
    "\n",
    "plt.tight_layout()\n",
    "plt.show()"
   ]
  },
