    "import plotly.express as px\n",
    "\n",
    "avg_score = (\n",
    "    df.groupby(\n",
    "        [\"study_hours_per_day\", \"pass_status\"],\n",
    "        as_index=False\n",
    "    )[\"exam_score\"]\n",
    "    .mean()\n",
    ")\n",
    "\n",
    "fig = px.line(\n",
    "    avg_score,\n",
    "    x=\"study_hours_per_day\",\n",
    "    y=\"exam_score\",\n",
    "    color=\"pass_status\",\n",
    "    markers=True,\n",
    "    title=\"Average Exam Score by Study Hours and Pass/Fail Status\",\n",
    "    labels={\n",
    "        \"study_hours_per_day\": \"Study Hours per Day\",\n",
    "        \"pass_status\": \"Pass / Fail\"\n",
    "    }\n",
    ")\n",
    "\n",
    "fig.show()"
