  {
   "cell_type": "code",
   "execution_count": 56,
   "id": "a5a48f68",
   "metadata": {},
   "outputs": [
    {
     "data": {
      "image/png": "",
      "text/plain": [
       "<Figure size 1300x700 with 2 Axes>"
      ]
     },
     "metadata": {},
     "output_type": "display_data"
    }
   ],
   "source": [
    "\n",
    "\n",
    "# ==========================================\n",
    "# Study Hours Analysis\n",
    "# ==========================================\n",
    "\n",
    "# Calculate Pass, Fail and Average Score\n",
    "study_hours_analysis = (\n",
    "    df.groupby(\"study_hours_group\", observed=True)\n",
    "      .agg(\n",
    "          Pass=(\"pass_status\", lambda x: (x == 1).sum()),\n",
    "          Fail=(\"pass_status\", lambda x: (x == 0).sum()),\n",
    "          Average_Score=(\"exam_score\", \"mean\")\n",
    "      )\n",
    ")\n",
    "\n",
    "# Total students\n",
    "study_hours_analysis[\"Total\"] = (\n",
    "    study_hours_analysis[\"Pass\"] +\n",
    "    study_hours_analysis[\"Fail\"]\n",
    ")\n",
    "\n",
    "# Pass & Fail percentages\n",
    "study_hours_analysis[\"Pass %\"] = (\n",
    "    study_hours_analysis[\"Pass\"] /\n",
    "    study_hours_analysis[\"Total\"] * 100\n",
    ")\n",
    "\n",
    "study_hours_analysis[\"Fail %\"] = (\n",
    "    study_hours_analysis[\"Fail\"] /\n",
    "    study_hours_analysis[\"Total\"] * 100\n",
    ")\n",
    "\n",
    "# ==========================================\n",
    "# Plot\n",
    "# ==========================================\n",
    "\n",
    "x = np.arange(len(study_hours_analysis))\n",
    "width = 0.35\n",
    "\n",
    "fig, ax1 = plt.subplots(figsize=(13, 7))\n",
    "\n",
    "# Pass bars\n",
    "bars_pass = ax1.bar(\n",
    "    x - width/2,\n",
    "    study_hours_analysis[\"Pass\"],\n",
    "    width,\n",
    "    label=\"Pass\",\n",
    "    color=\"green\"\n",
    ")\n",
    "\n",
    "# Fail bars\n",
    "bars_fail = ax1.bar(\n",
    "    x + width/2,\n",
    "    study_hours_analysis[\"Fail\"],\n",
    "    width,\n",
    "    label=\"Fail\",\n",
    "    color=\"red\"\n",
    ")\n",
    "\n",
    "# ==========================================\n",
    "# Count + Percentage Labels\n",
    "# ==========================================\n",
    "\n",
    "for i, bar in enumerate(bars_pass):\n",
    "\n",
    "    height = bar.get_height()\n",
    "    percentage = study_hours_analysis[\"Pass %\"].iloc[i]\n",
    "\n",
    "    ax1.text(\n",
    "        bar.get_x() + bar.get_width()/2,\n",
    "        height,\n",
    "        f\"{int(height):,}\\n({percentage:.1f}%)\",\n",
    "        ha=\"center\",\n",
    "        va=\"bottom\",\n",
    "        fontsize=9\n",
    "    )\n",
    "\n",
    "\n",
    "for i, bar in enumerate(bars_fail):\n",
    "\n",
    "    height = bar.get_height()\n",
    "    percentage = study_hours_analysis[\"Fail %\"].iloc[i]\n",
    "\n",
    "    ax1.text(\n",
    "        bar.get_x() + bar.get_width()/2,\n",
    "        height,\n",
    "        f\"{int(height):,}\\n({percentage:.1f}%)\",\n",
    "        ha=\"center\",\n",
    "        va=\"bottom\",\n",
    "        fontsize=9\n",
    "    )\n",
    "\n",
    "# ==========================================\n",
    "# Second Y-Axis for Average Score\n",
    "# ==========================================\n",
    "\n",
    "ax2 = ax1.twinx()\n",
    "\n",
    "line = ax2.plot(\n",
    "    x,\n",
    "    study_hours_analysis[\"Average_Score\"],\n",
    "    marker=\"o\",\n",
    "    linewidth=2.5,\n",
    "    color=\"blue\",\n",
    "    label=\"Average Exam Score\"\n",
    ")\n",
    "\n",
    "# Add score labels\n",
    "for i, score in enumerate(study_hours_analysis[\"Average_Score\"]):\n",
    "\n",
    "    ax2.text(\n",
    "        x[i],\n",
    "        score + 1,\n",
    "        f\"{score:.1f}\",\n",
    "        ha=\"center\",\n",
    "        fontsize=9,\n",
    "        color=\"blue\",\n",
    "        fontweight=\"bold\"\n",
    "    )\n",
    "\n",
    "# ==========================================\n",
    "# Labels & Title\n",
    "# ==========================================\n",
    "\n",
    "ax1.set_title(\n",
    "    \"Pass, Fail & Average Exam Score by Study Hours\",\n",
    "    fontsize=15,\n",
    "    fontweight=\"bold\"\n",
    ")\n",
    "\n",
    "ax1.set_xlabel(\"Study Hours per Day\")\n",
    "ax1.set_ylabel(\"Number of Students\")\n",
    "ax2.set_ylabel(\"Average Exam Score\")\n",
    "\n",
    "ax1.set_xticks(x)\n",
    "ax1.set_xticklabels(study_hours_analysis.index)\n",
    "\n",
    "# Light horizontal grid\n",
    "ax1.yaxis.grid(\n",
    "    True,\n",
    "    linestyle=\"--\",\n",
    "    linewidth=0.6,\n",
    "    alpha=0.3\n",
    ")\n",
    "\n",
    "ax1.set_axisbelow(True)\n",
    "\n",
    "# ==========================================\n",
    "# Combined Legend\n",
    "# ==========================================\n",
    "\n",
    "bars_legend, labels_legend = ax1.get_legend_handles_labels()\n",
    "line_legend, line_labels = ax2.get_legend_handles_labels()\n",
    "\n",
    "ax1.legend(\n",
    "    bars_legend + line_legend,\n",
    "    labels_legend + line_labels,\n",
    "    loc=\"upper left\"\n",
    ")\n",
    "\n",
    "plt.tight_layout()\n",
    "plt.show()"
   ]
  },
