    "    x=\"index\",\n",
    "    y=[\"Previous Year %\", \"Current Year %\"],\n",
    "    barmode=\"group\",\n",
    "    title=\"Comparison of Student Score Distribution: Previous vs Current Year\",\n",
    "    labels={\n",
    "        \"index\": \"Score Group\",\n",
    "        \"value\": \"Percentage of Students (%)\",\n",
    "        \"variable\": \"Year\"\n",
    "    },\n",
    "    text_auto=\".1f\"\n",
    ")\n",
    "\n",
    "fig.update_layout(\n",
    "    xaxis_title=\"Score Group\",\n",
    "    yaxis_title=\"Students (%)\",\n",
    "    legend_title=\"Year\"\n",
    ")\n",
    "\n",
    "fig.show()"
